INSERT INTO `blog_posts_i18n`
  (`blog_post_id`, `locale`, `title`, `slug`, `excerpt`, `content`, `meta_title`, `meta_description`)
VALUES
(
  '50000000-0000-4000-8000-000000000001',
  'tr',
  '5 Yaş İngilizce Ders Programı: Haftalık Örnek Plan',
  '5-yas-ingilizce-ders-programi',
  '5 yaş İngilizce ders programı; 20-25 dakikalık, oyun, hikâye, şarkı ve kısa kalıpları aynı haftalık hedefte birleştiren tekrar edilebilir bir akış olmalıdır.',
  '<article data-seo-block="5-age-plan-20260904"><p><strong>5 yaş İngilizce ders programı nasıl olmalı?</strong> Beş yaşta program, haftada aynı kelime ve kısa cümle kalıbını farklı etkinliklerle tekrar ettirmelidir. Bir ders için 20-25 dakika çoğu grup açısından yeterlidir. Tanıtım, hareketli oyun, hikâye veya şarkı ve kısa kapanış aynı hedefe bağlandığında çocuk dili ezberlemek yerine kullanmaya başlar.</p><h2>5 yaşta temel öğrenme hedefleri</h2><p>Bu yaşta amaç uzun cümleler ya da dil bilgisi kuralı öğretmek değildir. Çocuğun yönergeyi anlaması, doğru görseli seçmesi, tek kelimeden kısa kalıba geçmesi ve hikâye sırasını takip etmesi beklenir. <em>I see red</em>, <em>I like apples</em>, <em>It is a cat</em> gibi kısa yapılar görsel ve oyunla desteklenebilir.</p><ul><li>10-15 kelimelik bir tema grubunu tanımak</li><li>İki veya üç kelimelik kısa kalıplara katılmak</li><li>Stand up, show me, point to gibi yönergeleri takip etmek</li><li>Şarkı ve hikâyedeki tekrar eden ifadeyi fark etmek</li><li>Kart seçme, eşleştirme ve sıraya koyma görevlerini tamamlamak</li></ul><h2>Haftalık 5 yaş İngilizce programı örneği</h2><p>Örnek tema olarak renkler ve sınıf nesneleri seçilebilir. Hafta boyunca konu değiştirmek yerine aynı hedef farklı kanallarla tekrar edilir.</p><table><thead><tr><th>Gün</th><th>Ana hedef</th><th>Etkinlik</th><th>Kısa kalıp</th></tr></thead><tbody><tr><td>Pazartesi</td><td>Kelimeyi tanıma</td><td>Flashcard seçme ve hareket</td><td>Show me red</td></tr><tr><td>Salı</td><td>Kelimeyi söyleme</td><td>Renk avı ve eşleştirme</td><td>I see red</td></tr><tr><td>Çarşamba</td><td>Bağlam kurma</td><td>Kısa hikâye ve görsel sıralama</td><td>It is red</td></tr><tr><td>Perşembe</td><td>Ritimle tekrar</td><td>Şarkı ve hareket oyunu</td><td>Red, blue, yellow</td></tr><tr><td>Cuma</td><td>Gözlem ve pekiştirme</td><td>İstasyon oyunu ve mini görev</td><td>What color is it?</td></tr></tbody></table><h2>25 dakikalık ders akışı</h2><ol><li><strong>3 dakika karşılama:</strong> Her derste aynı kısa hello rutini kullanılır.</li><li><strong>5 dakika tanıtım:</strong> En fazla dört yeni kart gösterilir; öğretmen uzun açıklama yapmaz.</li><li><strong>7 dakika oyun:</strong> Çocuk doğru kartı bulur, taşır, eşleştirir veya karaktere verir.</li><li><strong>5 dakika hikâye ya da şarkı:</strong> Aynı hedef kelime başka bir bağlamda tekrar edilir.</li><li><strong>5 dakika kapanış:</strong> Her çocuk küçük bir seçim yapar; öğretmen gözlem notu alır.</li></ol><h2>5 yaş İngilizce konuları hangi sırayla verilebilir?</h2><p>Tanışma ve sınıf yönergeleriyle başlayıp renkler, sayılar, aile, hayvanlar, yiyecekler, oyuncaklar, vücut, duygular, hava durumu ve günlük rutinlere ilerlemek uygundur. Konu sırasından daha önemli olan, her temanın önceki kelime ve kalıplarla bağ kurmasıdır. Yıllık konu haritası için <a href="/tr/blog/anaokulu-ingilizce-konulari">anaokulu İngilizce konuları rehberine</a> bakabilirsiniz.</p><h2>İlerleme nasıl ölçülür?</h2><p>Beş yaşta sınav yerine gözlenebilir davranışlar izlenir. Çocuğun doğru kartı seçmesi, yönergeye tepki vermesi, şarkının tekrarına katılması ve kısa kalıbı destekle kullanması ilerleme kanıtıdır. Her hafta üç maddelik bir gözlem listesi öğretmenler arasında ortak standart kurulmasını sağlar.</p><h2>Sık yapılan planlama hataları</h2><p>Bir derste çok fazla yeni kelime vermek, her gün konu değiştirmek ve çocuktan sürekli bireysel cevap istemek katılımı düşürür. Çalışma sayfasını dersin merkezine koymak da hareket ve iletişim alanını daraltır. Çalışma sayfası, oyun ve hikâyeden sonra sakin pekiştirme amacıyla kullanılmalıdır.</p><h2>Woody ile haftalık programı kurmak</h2><p>Woody and Friends; kitap, öğretmen planı, kart, oyun, StoryLand hikâyesi ve MusicLand şarkısını aynı kazanıma bağlar. Böylece öğretmen her etkinliği ayrı ayrı aramak yerine haftalık hedefi tutarlı bir sırayla uygular. Yaşlar arasındaki farkı görmek için <a href="/tr/blog/4-5-6-yas-ingilizce-egitimi">4-5-6 yaş karşılaştırma rehberini</a>, bir sonraki basamak için <a href="/tr/blog/6-yas-ingilizce-egitimi">6 yaş İngilizce programını</a> inceleyebilirsiniz.</p><p>Kurumunuzda yaşa göre sürdürülebilir bir yapı kurmak için <a href="/tr/preschool">Woody Okul Serisi</a> sayfasını; set ve materyaller için <a href="/tr/store">Woody mağazasını</a> ziyaret edebilirsiniz.</p><h2>Sıkça Sorulan Sorular</h2><h3>5 yaş İngilizce dersi kaç dakika olmalı?</h3><p>Gruba göre 20-25 dakika uygundur. Tek uzun etkinlik yerine kısa ve birbirine bağlı adımlar kullanılmalıdır.</p><h3>Haftada kaç gün İngilizce yapılmalı?</h3><p>İki ana ders ve diğer günlerde 5-10 dakikalık kısa tekrarlar güçlü bir başlangıçtır. Kurum düzenine göre sıklık artırılabilir.</p><h3>5 yaşta yazma çalışması gerekir mi?</h3><p>Öncelik dinleme, anlama ve sözlü katılımdır. Çizgi, eşleştirme ve görsel görevler kullanılabilir; yoğun yazma beklenmemelidir.</p><h3>Çocuk cevap vermiyorsa ne yapılmalı?</h3><p>Kart gösterme veya hareketle tepki vermesine izin verin. Sessiz katılım da öğrenmenin bir aşamasıdır.</p></article>',
  '5 Yaş İngilizce Ders Programı | Haftalık Örnek Plan',
  '5 yaş İngilizce ders programı için 20-25 dakikalık ders akışı, haftalık tablo, konu sırası, oyun, hikâye, şarkı ve gözlem önerileri.'
),
(
  '50000000-0000-4000-8000-000000000002',
  'tr',
  '4 Yaş İngilizce Etkinlikleri: Sınıfta 10 Oyun Fikri',
  '4-yas-ingilizce-etkinlikleri',
  '4 yaş İngilizce etkinlikleri kısa yönerge, görsel destek, hareket ve tekrar içermeli; çocuk konuşmaya zorlanmadan seçim ve taklitle katılabilmelidir.',
  '<article data-seo-block="4-age-activities-20260904"><p><strong>4 yaş İngilizce etkinlikleri nasıl seçilir?</strong> Etkinlik tek hedefli, kısa ve hareketli olmalıdır. Dört yaşındaki çocuk bir kartı seçerek, nesneyi göstererek, hareketi taklit ederek veya tek kelime söyleyerek katılabilir. Beş-on dakikalık oyunların aynı kelimeleri hafta içinde tekrar etmesi, uzun çalışma sayfalarından daha uygulanabilir bir öğrenme akışı kurar.</p><h2>4 yaş için etkinlik tasarımının dört kuralı</h2><ul><li>Bir oyunda en fazla üç-dört yeni kelime kullanın.</li><li>Yönergeyi kısa söyleyin ve hareketle modelleyin.</li><li>Çocuğa konuşma dışında seçim, gösterme ve eşleştirme seçenekleri verin.</li><li>Aynı kelimeyi kart, oyun, şarkı ve hikâyede yeniden karşılaştırın.</li></ul><h2>1. Renk avı</h2><p>Öğretmen bir renk kartı gösterir ve <em>Find red</em> der. Çocuklar sınıfta o renkte bir nesne bulur. İlk turda yalnız bulma, sonraki turda <em>It is red</em> kalıbını öğretmenle tekrar etme yeterlidir.</p><h2>2. Woody hangi kartı seçti?</h2><p>Üç kart yere konur. Karakterin söylediği kelimeyi dinleyen çocuk doğru kartı Woody karakterine verir. Bu oyun dinleme ve seçme becerisini konuşma baskısı olmadan ölçer.</p><h2>3. Hayvan hareketleri</h2><p><em>Jump like a rabbit</em> veya <em>Walk like a bear</em> gibi kısa yönergeler kullanılır. Hayvan kartı, kelime ve hareket aynı anda eşleştiği için hatırlama kolaylaşır.</p><h2>4. Dokun ve göster</h2><p>Vücut bölümleri veya sınıf nesneleri için <em>Touch your nose</em>, <em>Show me the book</em> yönergeleri verilir. Oyun hızlı ilerler; yanlış cevap uzun açıklamayla kesilmez, öğretmen doğru hareketi yeniden modeller.</p><h2>5. Eksik kartı bul</h2><p>Üç kart gösterilir, çocuklar gözünü kapatınca biri saklanır. <em>What is missing?</em> sorusuna çocuk önce kartı gösterebilir, hazırsa kelimeyi söyleyebilir.</p><h2>6. Duygu aynası</h2><p>Happy, sad, surprised gibi duygular yüz ifadesiyle canlandırılır. Çocuk öğretmeni veya karakteri taklit eder. Duygu kelimesi gerçek bir ifadeyle eşleştiğinde anlamı daha kolay kurulur.</p><h2>7. Şarkıyı durdur</h2><p>Kısa bir şarkı çalarken çocuklar hareket eder. Müzik durduğunda öğretmen bir kart gösterir ve grup kelimeyi ya da ilgili hareketi tekrarlar. Şarkı, yalnız izlenen video değil etkinliğin ritmi olur.</p><h2>8. Hikâyeyi sırala</h2><p>Üç görselden oluşan mini hikâye okunur. Çocuklar görselleri başlangıç, orta ve son olarak dizer. Dört yaşta tam cümle beklemek yerine karakteri ve ana nesneyi bulması yeterlidir.</p><h2>9. Renkli istasyonlar</h2><p>Sınıfın farklı köşelerine renk veya sayı kartları yerleştirilir. Öğretmen hedefi söyler, çocuk doğru istasyona gider. Büyük grupta sırayı korumak için çocuklar küçük takımlara ayrılabilir.</p><h2>10. Sürpriz torbası</h2><p>Torbadaki üç gerçek nesneden biri dokunarak seçilir. Çocuk nesneyi çıkarır, grup öğretmenle birlikte adını söyler. Gerçek nesne kullanımı soyut kelimeyi somut deneyime dönüştürür.</p><h2>20 dakikalık örnek ders</h2><table><thead><tr><th>Süre</th><th>Adım</th><th>Amaç</th></tr></thead><tbody><tr><td>3 dk</td><td>Hello rutini</td><td>Güvenli başlangıç</td></tr><tr><td>4 dk</td><td>Üç kartı tanıtma</td><td>Dinleme ve taklit</td></tr><tr><td>7 dk</td><td>Hareketli oyun</td><td>Seçim ve tepki</td></tr><tr><td>4 dk</td><td>Şarkı veya mini hikâye</td><td>Bağlamda tekrar</td></tr><tr><td>2 dk</td><td>Goodbye ve kart seçimi</td><td>Gözlem</td></tr></tbody></table><h2>Etkinliklerde ilerleme nasıl izlenir?</h2><p>Doğru karta bakma, yönergeyle hareket etme, oyunun sırasını bekleme ve tekrar eden kelimeye katılma gözlenebilir kazanımlardır. Her çocuktan aynı gün konuşması beklenmez. Öğretmen küçük notlarla hangi desteğin işe yaradığını takip edebilir.</p><h2>Etkinlik seçerken yapılan hatalar</h2><p>Çok sayıda kart kullanmak, uzun açıklama yapmak, oyunu rekabete çevirmek ve videoyu pasif biçimde uzun süre izletmek dikkat kaybına yol açar. Dört yaş etkinliği basit başlamalı; grup hazırsa ikinci yönerge eklenmelidir.</p><h2>Yaşa göre doğru basamağa bağlayın</h2><p>Dört yaşta seçim ve taklit merkezdeyken beş yaşta kısa kalıp, altı yaşta basit soru-cevap öne çıkar. Bu ilerlemeyi <a href="/tr/blog/4-5-6-yas-ingilizce-egitimi">4-5-6 yaş İngilizce planında</a> karşılaştırabilir, yıllık tema seçimi için <a href="/tr/blog/anaokulu-ingilizce-konulari">anaokulu İngilizce konuları</a> rehberini kullanabilirsiniz.</p><p>Oyun, kart, hikâye ve dijital tekrarı aynı hedefte birleştirmek için <a href="/tr/preschool">Woody Okul Serisi</a> ve <a href="/tr/digital-content">Woody dijital içeriklerini</a> inceleyebilirsiniz.</p><h2>Sıkça Sorulan Sorular</h2><h3>4 yaş İngilizce için erken mi?</h3><p>Yaşa uygun, kısa ve oyun temelli bir yaklaşımla erken değildir. Hedef kural öğretmek değil dile güvenli aşinalık kazandırmaktır.</p><h3>4 yaş çocuğu kaç kelime öğrenmeli?</h3><p>Sabit bir sayı yerine az sayıda kelimenin farklı etkinliklerde anlamlı kullanımı izlenmelidir.</p><h3>Etkinlik kaç dakika sürmeli?</h3><p>Tek bir oyun çoğu grup için 5-7 dakika sürmelidir. Hareketli ve sakin adımlar dönüşümlü kullanılabilir.</p><h3>Evde hangi oyun uygulanabilir?</h3><p>Üç nesneyle renk avı, sürpriz torbası veya kart seçme oyunu beş dakikalık ev tekrarı için uygundur.</p></article>',
  '4 Yaş İngilizce Etkinlikleri | 10 Oyun Fikri',
  '4 yaş İngilizce etkinlikleri için sınıfta uygulanabilir 10 oyun, 20 dakikalık örnek ders, konu ve gözlem önerileri. Kısa, hareketli ve oyun temelli.'
),
(
  '50000000-0000-4000-8000-000000000003',
  'tr',
  'Anaokulu İngilizce Konuları: Yaşa Göre Yıllık Liste',
  'anaokulu-ingilizce-konulari',
  'Anaokulu İngilizce konuları; sınıf rutinlerinden başlayıp renk, sayı, aile, hayvan, yiyecek, duygu ve günlük yaşama ilerleyen yaşa göre kademeli bir haritayla planlanmalıdır.',
  '<article data-seo-block="preschool-topics-20260904"><p><strong>Anaokulu İngilizce konuları nelerdir?</strong> Temel konu listesi selamlaşma ve sınıf yönergeleri, renkler, sayılar, aile, hayvanlar, oyuncaklar, yiyecekler, vücut bölümleri, kıyafetler, duygular, hava durumu ve günlük rutinlerden oluşur. Etkili bir program yalnız konu başlığı sıralamaz; her temayı yaşa uygun kelime, kısa kalıp, oyun, hikâye ve gözlenebilir kazanımla eşleştirir.</p><h2>Yıllık anaokulu İngilizce konu haritası</h2><table><thead><tr><th>Dönem</th><th>Konu</th><th>Örnek kelime</th><th>İletişim hedefi</th></tr></thead><tbody><tr><td>Eylül</td><td>Selamlaşma ve sınıf rutini</td><td>hello, goodbye, sit, stand</td><td>Yönergeye tepki</td></tr><tr><td>Ekim</td><td>Renkler ve şekiller</td><td>red, blue, circle, square</td><td>Seçme ve gösterme</td></tr><tr><td>Kasım</td><td>Sayılar ve oyuncaklar</td><td>one-five, ball, doll, car</td><td>Sayma ve adlandırma</td></tr><tr><td>Aralık</td><td>Aile ve ev</td><td>mother, father, room, door</td><td>Kendi çevresini tanıma</td></tr><tr><td>Ocak</td><td>Hayvanlar</td><td>cat, dog, bird, rabbit</td><td>Ses ve hareket eşleştirme</td></tr><tr><td>Şubat</td><td>Vücut ve duygular</td><td>head, hand, happy, sad</td><td>Yönerge ve duygu ifadesi</td></tr><tr><td>Mart</td><td>Yiyecek ve içecek</td><td>apple, milk, bread, water</td><td>Sevdiğini belirtme</td></tr><tr><td>Nisan</td><td>Hava ve kıyafet</td><td>sunny, rainy, coat, shoes</td><td>Duruma uygun seçim</td></tr><tr><td>Mayıs</td><td>Doğa ve ulaşım</td><td>tree, flower, car, bus</td><td>Çevreyi betimleme</td></tr><tr><td>Haziran</td><td>Genel tekrar</td><td>Yılın hedef kelimeleri</td><td>Oyun ve hikâyede kullanma</td></tr></tbody></table><h2>3, 4, 5 ve 6 yaşta aynı konu nasıl değişir?</h2><p>Konu aynı kalabilir, beklenti değişmelidir. Renkler temasında 3 yaş çocuğu doğru karta bakar veya dokunur; 4 yaş çocuğu rengi seçer ve taklit eder; 5 yaş çocuğu <em>I see red</em> gibi kısa kalıba katılır; 6 yaş çocuğu <em>What color is it?</em> sorusuna kısa cevap verir. Böylece yıllık plan tekrar ederken gelişim basamağı yükselir.</p><h2>Konu sırası nasıl belirlenir?</h2><p>Önce sınıfta her gün kullanılacak ifadeler verilmelidir. Hello, goodbye, sit down, stand up ve show me gibi rutinler sonraki bütün temaların taşıyıcısıdır. Ardından çocuğun görebildiği renk, oyuncak ve aile gibi somut alanlara; daha sonra duygu, hava ve günlük rutin gibi ilişki kurması gereken alanlara geçilebilir.</p><h2>Her konu için dört parçalı plan</h2><ol><li><strong>Kelime:</strong> Yaşa göre üç ile sekiz yeni kelime seçin.</li><li><strong>Kısa kalıp:</strong> Show me, I see, I like veya It is gibi tek bir yapı belirleyin.</li><li><strong>Etkinlik:</strong> Kart, hareketli oyun, şarkı ve hikâyeden en az ikisini bağlayın.</li><li><strong>Gözlem:</strong> Çocuğun hangi davranışla kazanımı göstereceğini önceden yazın.</li></ol><h2>Örnek: hayvanlar konusu için bir hafta</h2><p>Pazartesi dört hayvan kartı tanıtılır; salı hayvan hareketleri oynanır; çarşamba aynı karakterlerin bulunduğu kısa hikâye okunur; perşembe şarkı ve ses eşleştirmesi yapılır; cuma çocuk doğru kartı seçerek veya hayvanı canlandırarak öğrendiğini gösterir. Konu değişmez, çocuğun kelimeyle kurduğu bağ zenginleşir.</p><h2>Konu listesi ile müfredat aynı şey değildir</h2><p>Konu listesi ne öğretileceğini söyler. Müfredat ise konunun hangi sırayla, hangi kazanımla, hangi materyalle ve nasıl gözleneceğini açıklar. Yıllık yapının ayrıntısı için <a href="/tr/blog/anaokulu-ingilizce-mufredati-nasil-hazirlanir">anaokulu İngilizce müfredatı rehberini</a>, haftalık uygulama için <a href="/tr/blog/anaokulu-ingilizce-ders-plani-nasil-hazirlanir">ders planı rehberini</a> inceleyebilirsiniz.</p><h2>Materyal konuya nasıl bağlanır?</h2><p>Flashcard kelimeyi görünür kılar, oyun çocuğun tepki vermesini sağlar, şarkı ritimle tekrar sunar, hikâye kelimeyi bağlama yerleştirir, worksheet veya craft ise sakin pekiştirme alanı oluşturur. Bu araçların her biri farklı bir konuya dağılmamalı; aynı haftalık hedefi desteklemelidir.</p><h2>İlerleme ve veli iletişimi</h2><p>Veliye yalnız bu ay hayvanları işledik demek yerine, çocuğun dört hayvanı ayırt ettiği, iki yönergeye tepki verdiği ve hikâyedeki karakteri bulduğu açıklanabilir. Böyle bir kazanım dili kurumun programını görünür ve güvenilir hale getirir.</p><h2>Woody konu akışı</h2><p>Woody and Friends konu, öğretmen planı, kitap, kart, oyun, MusicLand şarkısı ve StoryLand hikâyesini aynı kazanım çevresinde düzenler. Yaşa göre ders örnekleri için <a href="/tr/blog/4-yas-ingilizce-etkinlikleri">4 yaş etkinliklerini</a>, <a href="/tr/blog/5-yas-ingilizce-ders-programi">5 yaş haftalık programını</a> ve <a href="/tr/blog/6-yas-ingilizce-egitimi">6 yaş rehberini</a> kullanabilirsiniz.</p><p>Kurumunuza uygun konu ve materyal sistemini değerlendirmek için <a href="/tr/preschool">Woody Okul Serisi</a> sayfasını ziyaret edin.</p><h2>Sıkça Sorulan Sorular</h2><h3>Anaokulunda bir ayda kaç İngilizce konusu işlenmeli?</h3><p>Grubun sıklığına göre bir ana tema ve onu destekleyen alt başlıklar yeterlidir. Hızlı konu değişiminden çok tekrar kalitesi önemlidir.</p><h3>İngilizce alfabesi ilk konu olmalı mı?</h3><p>Okul öncesinde öncelik dinleme, yönerge ve anlamlı kelimelerdir. Alfabe şarkı ve ses farkındalığı olarak desteklenebilir; programın tek omurgası olmamalıdır.</p><h3>Her yaş aynı kelimeleri öğrenebilir mi?</h3><p>Aynı temayı paylaşabilir; kelime sayısı, beklenen tepki ve kullanılan cümle kalıbı yaşa göre farklılaşmalıdır.</p><h3>Konular evde nasıl tekrar edilir?</h3><p>Okul o haftanın üç-dört kelimesini ve tek kısa kalıbını paylaşabilir. Veli bunları beş dakikalık nesne bulma, kart seçme veya şarkı rutiniyle tekrar edebilir.</p></article>',
  'Anaokulu İngilizce Konuları | Yaşa Göre Yıllık Liste',
  'Anaokulu İngilizce konuları için yaşa göre yıllık liste, aylık tema tablosu, örnek hafta, kelime-kalıp-etkinlik-kazanım planı ve materyal önerileri.'
)
ON DUPLICATE KEY UPDATE
  `title` = VALUES(`title`),
  `slug` = VALUES(`slug`),
  `excerpt` = VALUES(`excerpt`),
  `content` = VALUES(`content`),
  `meta_title` = VALUES(`meta_title`),
  `meta_description` = VALUES(`meta_description`);

-- Existing authority pages pass relevance to the new, non-overlapping intents.
UPDATE `blog_posts_i18n`
   SET `content` = CASE
     WHEN LOCATE('data-seo-block="age-cluster-links-20260904"', `content`) = 0 THEN CONCAT(
       `content`,
       '<section data-seo-block="age-cluster-links-20260904"><h2>Yaşa göre ayrıntılı uygulama rehberleri</h2><p>Karşılaştırmadan doğrudan sınıf planına geçmek için <a href="/tr/blog/4-yas-ingilizce-etkinlikleri">4 yaş İngilizce etkinliklerini</a>, <a href="/tr/blog/5-yas-ingilizce-ders-programi">5 yaş haftalık ders programını</a> ve <a href="/tr/blog/6-yas-ingilizce-egitimi">6 yaş İngilizce rehberini</a> inceleyebilirsiniz. Yıl boyunca işlenecek tema sırası için <a href="/tr/blog/anaokulu-ingilizce-konulari">anaokulu İngilizce konuları listesini</a> kullanın.</p></section>'
     )
     ELSE `content`
   END
 WHERE `locale` = 'tr'
   AND `slug` IN ('3-6-yas-ingilizce-egitimi-nasil-olmali', '4-5-6-yas-ingilizce-egitimi', '6-yas-ingilizce-egitimi');

UPDATE `blog_posts` b
INNER JOIN `blog_posts_i18n` i ON i.blog_post_id = b.id
   SET b.updated_at = CURRENT_TIMESTAMP(3)
 WHERE i.locale = 'tr'
   AND i.slug IN (
     '3-6-yas-ingilizce-egitimi-nasil-olmali',
     '4-5-6-yas-ingilizce-egitimi',
     '6-yas-ingilizce-egitimi',
     '4-yas-ingilizce-etkinlikleri',
     '5-yas-ingilizce-ders-programi',
     'anaokulu-ingilizce-konulari'
   );
